export function earnedOriginGate({
  originLandedMilestone = false,
  bootActivePlanetId = null, landedActivePlanetId = null,
  locationMode = null, controlMode = null,
  supported = null, bodyPose = null,
  fps = null, minFps = 15,
  av = null, requireNamedAnchors = true,
  anchors = null,
  requireOriginPlanetId = SIGNED_ORIGIN_PLANET_ID,
  requireOriginLandedAnchor = ORIGIN_LANDED_ANCHOR_ID
} = {}) {
  const problems = [];
  if (originLandedMilestone !== true) problems.push('story:ch13-origin-landed never latched: the return flight did not physically land');
  if (!landedActivePlanetId) problems.push('no live activePlanetId was read at the landing: the active origin is UNMEASURED');
  else if (bootActivePlanetId && landedActivePlanetId === bootActivePlanetId) {
    problems.push(`activePlanetId is still the departure body ${bootActivePlanetId}: no world handoff was measured`);
  }
  // EXACT signed Origin id, not merely "different from departure".
  if (requireOriginPlanetId != null && landedActivePlanetId != null
    && landedActivePlanetId !== requireOriginPlanetId) {
    problems.push(`landed activePlanetId ${JSON.stringify(landedActivePlanetId)} is not the signed Origin ${JSON.stringify(requireOriginPlanetId)}: a different body is not the Origin landing`);
  }
  if (locationMode !== 'surface') problems.push(`systemFlight.locationMode=${JSON.stringify(locationMode)} is not "surface"`);
  if (controlMode !== 'fps') problems.push(`spaceFlight.controlMode=${JSON.stringify(controlMode)} is not on-foot "fps"`);
  if (supported !== true) problems.push(`the mounted world does not support the body at its grounded pose (supported=${JSON.stringify(supported)})`);
  if (!Array.isArray(bodyPose) || bodyPose.length !== 3 || bodyPose.some((n) => typeof n !== 'number' || !Number.isFinite(n))) {
    problems.push('no finite grounded bodyPose was read');
  }
  if (typeof fps !== 'number' || !Number.isFinite(fps)) problems.push('no live frame rate was measured');
  else if (fps < minFps) problems.push(`live frame rate ${fps} < ${minFps}: the session is not really rendering`);
  const avr = avReading(av);
  const chapterAnchors = Array.isArray(anchors) ? [...anchors] : null;
  const avHasOriginLanded = requireOriginLandedAnchor == null
    ? null : avr.history.includes(requireOriginLandedAnchor);
  const chapterHasOriginLanded = requireOriginLandedAnchor == null || chapterAnchors === null
    ? null : chapterAnchors.includes(requireOriginLandedAnchor);
  if (requireNamedAnchors) {
    if (!avr.available) problems.push('state.signedSceneAv is unavailable: named AV anchor history is UNMEASURED');
    else if (avr.historyCount === 0) problems.push('signedSceneAv.activationHistoryAnchorIds is empty: no NAMED anchor has been activated (a key count is not evidence)');
    else if (requireOriginLandedAnchor != null && avHasOriginLanded !== true) {
      problems.push(`${requireOriginLandedAnchor} is ABSENT from signedSceneAv.activationHistoryAnchorIds [${avr.history.join(', ')}]: a non-empty history (e.g. lift only) does not name the landing`);
    }
  }
  if (anchors != null && !Array.isArray(anchors)) problems.push('commonGround diagnostic.anchors is not an array: wrong (flat) read path');
  if (requireOriginLandedAnchor != null) {
    if (chapterAnchors === null) problems.push('the chapter fired-anchor history was not read: the landing anchor is UNMEASURED on the chapter side');
    else if (chapterHasOriginLanded !== true) {
      problems.push(`${requireOriginLandedAnchor} is ABSENT from the chapter fired-anchor history [${chapterAnchors.join(', ')}]: the AV history alone is not the chapter's own record`);
    }
  }
  return {
    ok: problems.length === 0, problems,
    requirements: {
      originPlanetId: requireOriginPlanetId, originLandedAnchorId: requireOriginLandedAnchor,
      bothHistoriesRequired: requireOriginLandedAnchor != null,
      minFps, minFpsIsOperationalThreshold: true
    },
    measured: {
      originLandedMilestone, bootActivePlanetId, landedActivePlanetId, locationMode, controlMode,
      supported, bodyPose, fps, namedAnchorHistory: avr.history, firedAnchors: chapterAnchors,
      // RAW traces preserved: nothing measured is discarded by the tightening.
      avAvailable: avr.available, avAnchorId: avr.anchorId, avAnchorEvent: avr.anchorEvent,
      avBeat: avr.beat, avActivationSequence: avr.activationSequence,
      avHistoryCount: avr.historyCount, avRawKeyCountIsNotEvidence: avr.rawKeyCountIsNotEvidence,
      avHasOriginLanded, chapterHasOriginLanded
    }
  };
}

